args<-commandArgs(FALSE);script<-sub('^--file=','',args[grepl('^--file=',args)][1]);setwd(normalizePath(file.path(dirname(script),'..'),mustWork=TRUE))
source('R/model.R');x<-load_inputs();cal<-calibrate(x);a<-default_assumptions()
n<-0;check<-function(v,label){if(!isTRUE(v))stop(label);n<<-n+1};near<-function(x,y)max(abs(x-y),na.rm=TRUE)<1e-9
b<-project_model(x,a,cal);check(a$macro_mode=='prices' && a$domestic_price_growth==.025,'Price growth defaults to 2.5%');check(near(b$path$domestic_inflation[-1],rep(.025,36)),'Reference price path is 2.5%');ngdp_a<-modifyList(a,list(macro_mode='ngdp_per_capita'));ngdp<-project_model(x,ngdp_a,cal);check(near(ngdp$path$nominal_gdp_per_capita_growth[-1],rep(.032,36)),'Alternative fixed NGDP path remains available')
for(g in c(0,.012,.017))for(tot in c(-.2,0,.2)){
 z<-modifyList(a,list(productivity=g,tot_change=tot,macro_mode='prices',domestic_price_growth=.02,hours_growth=.001))
 m<-macro_path(x,z)
 check(near(m$domestic_inflation[-1],rep(.02,36)),'Selected price growth held fixed')
 check(near(m$nominal_gdp/m$nominal_gdp[1],m$real_output_index*m$domestic_price_index*m$income_effect),'Nominal accounting identity')
 check(near(m$nominal_gdp_per_capita_index,(m$nominal_gdp/m$nominal_gdp[1])/m$population_index),'Per-person identity')
 check(near(1+m$nominal_gdp_growth[-1],(1+m$nominal_gdp_per_capita_growth[-1])*(1+z$population_growth)),'Annual growth identity')
 check(near(m$nominal_hourly_wage_index,m$domestic_price_index*m$productivity_index),'Wages consistent with selected prices')
 check(near(m$nominal_gdp,macro_path(x,modifyList(z,list(ngdp_per_capita_growth=.08)))$nominal_gdp),'Inactive NGDP input has no effect')
}
p<-modifyList(a,list(macro_mode='prices'));m<-macro_path(x,p)
high<-macro_path(x,modifyList(p,list(productivity=.017)))
tot<-macro_path(x,modifyList(p,list(tot_change=.2)))
check(tail(high$nominal_gdp_per_capita,1)>tail(m$nominal_gdp_per_capita,1),'Higher productivity raises NGDP/person at fixed prices')
check(tot$nominal_gdp_per_capita_growth[2]>m$nominal_gdp_per_capita_growth[2],'ToT raises nominal income during transition')
check(near(tail(tot$nominal_gdp_per_capita_growth,1),tail(m$nominal_gdp_per_capita_growth,1)),'ToT level shift does not permanently raise growth')
pop<-macro_path(x,modifyList(p,list(population_growth=.02)))
check(near(pop$nominal_gdp_per_capita_index,m$nominal_gdp_per_capita_index),'Uniform population scaling does not change per-person income')
check(near(macro_path(x,modifyList(ngdp_a,list(domestic_price_growth=.08)))$nominal_gdp,ngdp$path$nominal_gdp),'Inactive price assumption has no effect')
check(near(macro_path(x,modifyList(ngdp_a,list(productivity=.017)))$nominal_gdp,ngdp$path$nominal_gdp),'NGDP mode preserves fixed nominal GDP')
check(near(macro_path(x,modifyList(ngdp_a,list(tot_change=.2)))$nominal_gdp,ngdp$path$nominal_gdp),'NGDP mode ToT changes implied prices')
s<-project_model(x,p,cal);check(near(subset(s$subfunctions,year==2030)$spending_bn,subset(b$subfunctions,year==2030)$spending_bn),'Shared spending anchors')
d<-scenario_attribution(x,p,cal);check(abs(sum(d$net_debt_change_pp)-tail(s$path$net_debt_pct-b$path$net_debt_pct,1))<1e-8,'Closure attribution reconciles')
for(v in list(list(macro_mode='invalid'),list(domestic_price_growth=-1),list(domestic_price_growth=NA_real_)))
 check(inherits(try(macro_path(x,modifyList(a,v)),silent=TRUE),'try-error'),'Invalid modes/rates rejected')
cat('PASS:',n,'nominal-growth/price-mode checks.\n')
